import{_ as e,o as t,c as i,a6 as r}from"./chunks/framework.QQy01QNh.js";const o="/xi-kari-skill/handbook/images/representation.svg",m=JSON.parse('{"title":"平均数准确，为什么仍看不见局部过载","description":"数据是否足够，取决于你到底要回答什么问题。","frontmatter":{"title":"平均数准确，为什么仍看不见局部过载","description":"数据是否足够，取决于你到底要回答什么问题。"},"headers":[],"relativePath":"concepts/representation.md","filePath":"concepts/representation.md"}'),l={name:"concepts/representation.md"};function n(s,a,c,h,p,d){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="平均数准确-为什么仍看不见局部过载" tabindex="-1">平均数准确，为什么仍看不见局部过载 <a class="header-anchor" href="#平均数准确-为什么仍看不见局部过载" aria-label="Permalink to &quot;平均数准确，为什么仍看不见局部过载&quot;">​</a></h1><p>同样平均排队10件，现场真的一样吗？</p><p><strong>数据是否足够，取决于你到底要回答什么问题。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文设定两个队列，超过15件就算某个位置过载。一个状态是第一处0件、第二处20件，另一个状态是两处各10件；二者的平均数都是10，局部过载的答案却不同。如果只保存平均数，后来再聪明的规则也不能从这个共同数字里还原被折叠的区别。平均数并没有算错：它仍能回答平均量和总量。</p><p>问题是用途变成了识别局部过载。原文接着加入最大值，这足以回答是否过载以及最大长度，却仍不知道哪个位置较大；遇到两个位置服务能力不同，位置又成为必要信息。因此，改进表示可以只补上当前问题需要的区别，不必恢复所有细节；也不能因为一个任务答得好，就宣布同一表示能够回答所有任务。</p><figure class="concept-figure"><img src="'+o+'" alt="相同平均数，两个不同答案"><figcaption>平均数保留了总量信息，却将本题所需的局部分布折叠了。</figcaption></figure><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>总量表示可准确回答总量，增加一个与任务相关的变量可修复部分不足</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-9">附录C.9 双队列的任务差异</a></li><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-6">附录C.6 F1任务恢复与最坏误差</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>双队列及阈值是原文人工模型。其961个等概率状态和错误率不是现实队列分布。补入最大值后的充分性，也不能直接推广到更多队列或不同动力条件。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./prediction.html">能预测常态，为什么未必能预测改变后的结果</a></li><li><a href="./joint-feasibility.html">每件事都做得到，为什么放在一起就做不到</a></li><li><a href="./../cases/mars-climate-orbiter.html">真实案例 · 火星气候轨道器：接口的单位差异</a></li></ul>',14)])])}const u=e(l,[["render",n]]);export{m as __pageData,u as default};
